public class ObjectNode_setAll_TriageGen2Test {

    private JsonNodeFactory factory;
    private ObjectNode objectNode;

    @Before
    public void setUp() {
        factory = JsonNodeFactory.instance;
        objectNode = factory.objectNode();
    }









    @Test
    public void testSetAllWithMixedNullAndNonNull() {
        Map<String, JsonNode> properties = new HashMap<>();
        properties.put("a", factory.textNode("a"));
        properties.put("b", null);
        properties.put("c", factory.nullNode()); // Explicit null node is different from Java null

        objectNode.setAll(properties);

        assertEquals(3, objectNode.size());
        assertFalse(objectNode.get("a").isNull());
        assertTrue(objectNode.get("b").isNull());
        assertTrue(objectNode.get("c").isNull());
    }
